{
  "steps": [
    "1) Triage & context gather: confirm alert metadata (root account, amount, rule), capture immediate account transactions and alert context to scope investigation.",
    "2) Financial flow mapping: trace outgoing/incoming flows from root account to identify scatter (many outflows) and gather (many inflows) patterns, build candidate fund-flow graphs and quantify amounts per counterparty.",
    "3) Data enrichment on key nodes: collect KYC/business registry info and counterparty transaction history for high-value or high-degree nodes to assess legitimacy and relationships.",
    "4) Conservation & anomaly analysis: compute flow conservation on constructed graphs, identify breaks or layering, compare alternate graph runs, and replan tracing on gaps.",
    "5) Regulatory screening: check applicable regulations and suspicious indicators associated with scatter-gather typologies and thresholds for INR 12,513,926.48.",
    "6) Hypothesis & risk scoring: synthesize findings into hypotheses (e.g., laundering, payroll, trade-based), assign risk levels and confidence, and identify next actionables (freeze, escalate, file STR/SAR).",
    "7) Reporting & critique: produce investigator report draft, run internal critique for completeness and technical consistency, finalize recommendations for escalation and follow-up."
  ],
  "handoffs": [
    {
      "task_id": "HO-FLOW",
      "target_agent": "flow_tracer",
      "objective": "Primary financial tracing: retrieve alert context and root account transactions for ACC-D0001-RT00; build candidate fund-flow graphs focused on INR 12,513,926.48 movements; compute flow conservation on initial graphs; produce prioritized list of high-value/high-degree counterparties and any unexplained sink/source nodes. Provide intermediate graphs and amounts to support re-tracing if gaps appear.",
      "allowed_tool_budget": 4
    },
    {
      "task_id": "HO-BENIGN",
      "target_agent": "benign_investigator",
      "objective": "Enrichment and legitimacy checks for top counterparties identified by flow_tracer: retrieve KYC profiles, check commercial registry entries, and obtain counterparty transaction histories for those entities/accounts. Assess whether counterparties show commercial activity consistent with flows and flag known benign patterns (payroll, supplier payments) vs suspicious indicators.",
      "allowed_tool_budget": 5
    },
    {
      "task_id": "HO-REG",
      "target_agent": "regulatory_analyst",
      "objective": "Gather regulatory context: search relevant domestic and cross-border AML/CFT regulations and internal reporting thresholds applicable to INR 12,513,926.48 and scatter-gather typology; supply clauses or guidance that inform escalation criteria and required reporting content.",
      "allowed_tool_budget": 2
    },
    {
      "task_id": "HO-CRITIC",
      "target_agent": "reporter_critic",
      "objective": "Final consistency and conservation check plus report review: recompute flow conservation on finalized graphs, validate numeric consistency, and perform a critical review of the draft investigator report for gaps, unclear assumptions, or missing evidence before finalization.",
      "allowed_tool_budget": 2
    }
  ]
}

{
  "steps": [
    "1) Triage & context pull: retrieve alert metadata and immediate account transaction history for root ACC-D0002-RT00 to understand timing, counterparties and transaction types.",
    "2) Trace fund flows outward/inward from ACC-D0002-RT00 to build a scatter-gather graph of downstream and upstream accounts and identify candidate endpoints and hub nodes.",
    "3) Enrich key counterparties and hub accounts with KYC, commercial registry records and historical counterparty behavior to assess intent, business purpose and legitimation indicators.",
    "4) Calculate and verify flow conservation across the constructed graph to confirm amounts match the alert amount (INR 6,345,062.05) and detect layering or value splits inconsistent with normal activity.",
    "5) Reconcile findings with regulatory policy: determine if the pattern matches known typologies for scatter-gather, money mule operations, or specific regulatory prohibitions; identify relevant clauses for escalation or filing requirements.",
    "6) Produce an investigational critique and recommended disposition (e.g., escalate to SAR/STR, monitor, close) including confidence, unresolved gaps, and suggested next steps for investigators or law enforcement."
  ],
  "handoffs": [
    {
      "task_id": "HO-FLOW",
      "target_agent": "flow_tracer",
      "objective": "Assemble the transaction graph for alert ALT-V2-D0002 (root ACC-D0002-RT00, amount INR 6,345,062.05). Actions: get alert context, pull full account transactions for the root and its 1-hop counterparties for the alert time window; find candidate fund flows (identify scatter and gather patterns); compute flow conservation on main subgraphs; produce a prioritized list of suspicious downstream hubs and timestamps. Deliverables: graph snapshot, list of top 10 suspicious accounts with rationale, and any inconsistencies in flow conservation.",
      "allowed_tool_budget": 4
    },
    {
      "task_id": "HO-BENIGN",
      "target_agent": "benign_investigator",
      "objective": "Enrich the prioritized accounts (top hubs and counterparties identified by flow_tracer) with identity and business information. Actions: get KYC profiles, check commercial registry for entities, pull counterparty transaction history to detect repeated scatter-gather behavior, and compute simple metrics (frequency, avg amounts). Deliverables: KYC summaries for each key account, registry findings, red/green flags per account, and recommended suspicion level.",
      "allowed_tool_budget": 5
    },
    {
      "task_id": "HO-REG",
      "target_agent": "regulatory_analyst",
      "objective": "Map the observed scatter-gather pattern to applicable regulation and reporting obligations. Actions: search regulations for scatter-gather, layering, mule networks, AML reporting thresholds in the applicable jurisdiction; get clause texts relevant to escalation, retention, and mandatory reporting for INR-equivalent thresholds. Deliverables: list of relevant statutes/clauses, citation excerpts, and recommended regulatory disposition (e.g., file STR/SAR, freeze, or monitor).",
      "allowed_tool_budget": 2
    },
    {
      "task_id": "HO-CRITIC",
      "target_agent": "reporter_critic",
      "objective": "Validate flow calculations and produce final investigator-facing summary and critique. Actions: recompute flow conservation for the final proposed graph, flag any residual accounting gaps, compute basic risk scoring metrics, and produce a concise recommended disposition with confidence and open questions. Deliverables: final conservation check, short write-up (one-page equivalent) with recommended next actions and items needing deeper probe or legal review.",
      "allowed_tool_budget": 2
    }
  ]
}

