      "allowed_tool_budget": 4
    },
    {
      "task_id": "HO-BENIGN",
      "target_agent": "benign_investigator",
      "objective": "For the root account and the top 10 counterparties identified by flow_tracer, retrieve KYC profiles, commercial registry entries, and counterparty transaction histories. Assess whether counterparties are legitimate businesses or individuals, flag shell/entity risk indicators, and estimate whether activity matches normal commercial patterns vs structuring/avoidance. Return a classification (benign/suspicious/unknown) with supporting evidence.",
      "allowed_tool_budget": 5
    },
    {
      "task_id": "HO-REG",
      "target_agent": "regulatory_analyst",
      "objective": "Search applicable regulations and guidance for scatter-gather typologies and reporting thresholds relevant to INR 3,706,351.03 and involved jurisdictions. Retrieve authoritative clauses and citation text that define reporting triggers, required timelines, and evidence standards to support SAR filing or internal escalation. Highlight any jurisdiction-specific nuances for entity types discovered by benign_investigator.",
      "allowed_tool_budget": 2
    },
    {
      "task_id": "HO-CRITIC",
      "target_agent": "reporter_critic",
      "objective": "Independently validate flow_tracer's conservation computations on the finalized graph sections and critique the investigative logic. Produce a concise list of residual uncertainties, alternative benign explanations, and confidence scores for each suspicious link, to inform final reporting decisions (do not generate the formal SAR—reserve that for final report step).",
      "allowed_tool_budget": 2
